"""Check reply node generated by aotn_node_helper."""

from typing import Any, ClassVar, Dict, List, Optional

from ...node_base import Node, NodeContext
from ...node_category import NodeCategory


class CheckReplyNode(Node):
    """Check a JSON reply against the fields you expect."""

    node_type: ClassVar[str] = 'check_reply_node'
    display_name: ClassVar[str] = 'Check reply'
    default_alias: ClassVar[str] = 'Check reply'
    description: ClassVar[str] = 'Check a JSON reply against the fields you expect'
    category: ClassVar[str] = NodeCategory.DATA
    primary_family: ClassVar[str] = 'Utility'
    tags: ClassVar[List[str]] = ['JSON', 'reply', 'check']
    icon_name: ClassVar[str] = 'list-check'
    color_hint: ClassVar[str] = 'grey'
    group: ClassVar[Optional[str]] = None
    selector_section: ClassVar[Optional[str]] = 'Transform'
    input_ports: ClassVar[List[str]] = ['input']
    output_ports: ClassVar[List[str]] = ['default']
    input_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'input': {'name': 'Reply', 'description': '', 'data_type': 'string', 'required': True, 'sources': ['upstream', 'vault', 'configured']}}
    output_port_metadata: ClassVar[Dict[str, Dict[str, Any]]] = {'default': {'name': 'Checked reply', 'description': '', 'data_type': 'var', 'required': True, 'to': ['downstream', 'vault'], 'pass_through': True}}
    default_config: ClassVar[Dict[str, Any]] = {'input_source': 'Upstream payload', 'input_vault_key': '', 'input': '', 'expected_fields': [{'id': 'summary', 'name': 'summary', 'kind': 'string', 'required': True}, {'id': 'cause', 'name': 'cause', 'kind': 'string', 'required': False}, {'id': 'next_step', 'name': 'next_step', 'kind': 'string', 'required': True}], 'allow_other_fields': False, 'max_reply': 16000, 'transient_output': True, 'dead_drop_passthrough': False, 'transient_outputs': [], 'vault_write': False, 'vault_write_key': '', 'vault_write_description': ''}
    config_schema: ClassVar[Dict[str, Dict[str, Any]]] = {'input_source': {'type': 'select', 'label': 'Input source', 'options': ['Upstream payload', 'Vault', 'Configured'], 'tab': 'Source', 'section': 'Required Inputs'}, 'input_vault_key': {'type': 'string', 'label': 'Input Vault key', 'required': False, 'tab': 'Source', 'section': 'Required Inputs', 'vault_type': 'string', 'visible_when': {'input_source': 'Vault'}}, 'input': {'type': 'multiline', 'label': 'Reply', 'tab': 'Parameters', 'height': 5, 'description': 'Preview only. e/Enter: edit full text; P: replace.', 'preview': True, 'visible_when': {'input_source': 'Configured'}}, 'expected_fields': {'type': 'object_list', 'label': 'Expected fields', 'tab': 'Parameters', 'add_label': 'Add field', 'remove_label': 'Remove field', 'id_prefix': 'field_', 'min_items': 1, 'max_items': 32, 'unique_by': 'name', 'item_schema': {'name': {'type': 'string', 'label': 'Field name', 'required': True, 'pattern': '[A-Za-z_][A-Za-z0-9_-]{0,63}'}, 'kind': {'type': 'select', 'label': 'Type', 'options': [['Text', 'string'], ['Number', 'number'], ['Yes or no', 'boolean'], ['List', 'list'], ['Record', 'object'], ['Empty', 'null']], 'default': 'string'}, 'required': {'type': 'boolean', 'label': 'Required', 'default': True}}, 'presentation': 'contract_table', 'hint': 'Checks that a reply has the fields below. If not, it takes the error path.'}, 'allow_other_fields': {'type': 'boolean', 'label': 'Extra fields are OK', 'tab': 'Parameters'}, 'max_reply': {'type': 'integer', 'label': 'Max reply (characters)', 'tab': 'Parameters', 'description': '', 'min': 1, 'max': 64000}}
    ui_hints: ClassVar[Dict[str, Any]] = {}
    error_definitions: ClassVar[List[Dict[str, Any]]] = [{'code': 'shape_invalid', 'description': 'Check the expected fields.', 'retryable': False}, {'code': 'reply_mismatch', 'description': "Reply didn't match.", 'retryable': False}]

    error_definitions.append(dict(code='selection_invalid', description='Candidate IDs or roles are invalid.', retryable=False))
    default_config['validate_selection'] = False
    config_schema['validate_selection'] = dict(type='boolean', label='Validate candidate selection')

    async def execute(self, context: NodeContext) -> None:
        from ... import text_lines
        from ...node_errors import NodeError
        from ...system_access import finish
        try:
            text_lines.validate_outputs(self.config, extra=False)
            from ...reply_shape import check
            value = await check(text_lines.source(self.config, context), self.config['expected_fields'],
                                self.config['max_reply'], self.config['allow_other_fields'])
            if self.config.get('validate_selection'):
                from ...palette_selection import validate_analysis
                from ...node_factory import NodeFactory
                validate_analysis(NodeFactory(), value)
            finish(self, context, value, 'var')
        except NodeError as exc:
            context.signal_error(exc)
